import array
import pythoncom

def to_variant_point(point_list):
    """Convert [x, y, z] to VARIANT for AutoCAD"""
    return pythoncom.VT_ARRAY | pythoncom.VT_R8, array.array('d', point_list)

center_variant = to_variant_point([0, 0, 0])

def validate_coordinates(coords):
    """Validate coordinate list contains 2 or 3 numeric values"""
    if not isinstance(coords, (list, tuple)) or len(coords) not in [2, 3]:
        raise ValueError("Coordinates must be 2D or 3D list/tuple")
    if not all(isinstance(c, (int, float)) for c in coords):
        raise ValueError("All coordinates must be numeric")
    return True

